// /frontend-react/src/components/MedicalDashboard.js

import React from 'react';
import HeaderBar from './HeaderBar';

const SubIcon = ({ name, emoji, goToPage, pageTarget, isEasyMode }) => (
    <div 
        onClick={() => goToPage(pageTarget)}
        style={{
            padding: '15px',
            margin: '15px 15%', 
            borderRadius: '15px',
            width: '70%', 
            textAlign: 'center',
            backgroundColor: '#fff', 
            border: '1px solid #ddd', 
            boxShadow: '0 4px 10px rgba(0,0,0,0.1)', 
            cursor: 'pointer',
            transition: 'transform 0.1s',
            overflow: 'hidden'
        }}
    >
        {/* Top Section: Emoji */}
        <div style={{ paddingBottom: '10px', borderBottom: '2px solid #007bff20' }}>
             <span role="img" aria-label={name} style={{
                fontSize: isEasyMode ? '70px' : '45px', 
                display: 'block', 
                marginBottom: '5px'
            }}>{emoji}</span>
        </div>

        {/* Bottom Section: Label/Action */}
        <div style={{ 
             paddingTop: '10px',
             backgroundColor: '#1A73E8', // Blue color band
             margin: '-15px', 
             marginTop: '10px'
        }}>
            <p style={{
                fontWeight: 'bold', 
                fontSize: isEasyMode ? '24px' : '18px', 
                color: 'white', 
                margin: '0',
                padding: '10px'
            }}>{name}</p>
        </div>
    </div>
);

function MedicalDashboard({ isEasyMode, goToPage }) {
    return (
        <div style={{ position: 'relative', minHeight: '400px', paddingBottom: '20px' }}>
            
            <HeaderBar
                title="Medical Menu"
                onBackClick={() => goToPage('dashboard')}
                isEasyMode={isEasyMode}
            />
            
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', paddingTop: '15px' }}>
                <SubIcon name="Appointments" emoji="🗓️" pageTarget="appointment" goToPage={goToPage} isEasyMode={isEasyMode}/>
                <SubIcon name="Transportation" emoji="🚑" pageTarget="transport" goToPage={goToPage} isEasyMode={isEasyMode}/>
                <SubIcon name="Medicine" emoji="💊" pageTarget="medicine" goToPage={goToPage} isEasyMode={isEasyMode}/>
            </div>
        </div>
    );
}

export default MedicalDashboard;
